31	        String region = OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
32	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
33	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
34	        String base = region + "-" + hash8(telephone + lastName);
35	        owner.setCustomerCode(deDuplicate(base, owner, ownerRepository));
36	    }
