39	     * Returns {@code base} if no existing owner already uses it, otherwise {@code base-<n>} with the
40	     * smallest {@code n >= 2} that is not already taken by an existing owner.
41	     */
42	    private static String deDuplicate(String base, Owner owner, OwnerRepository ownerRepository) {
43	        Set<String> taken = new HashSet<>();
44	        for (Owner existing : ownerRepository.findAll()) {
45	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
46	                continue; // never compare the new owner against itself
47	            }
48	            String code = existing.getCustomerCode();
49	            if (code != null) {
50	                taken.add(code);
51	            }
52	        }
53	        if (!taken.contains(base)) {
54	            return base;
55	        }
56	        for (int n = 2; ; n++) {
57	            String candidate = base + "-" + n;
58	            if (!taken.contains(candidate)) {
59	                return candidate;
60	            }
61	        }
62	    }
63	
64	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
65	    private static String hash8(String value) {
66	        try {
67	            byte[] digest = MessageDigest.getInstance("SHA-256")
