70	            for (int i = 0; i < 4; i++) {
71	                sb.append(String.format("%02X", digest[i]));
72	            }
73	            return sb.toString();
74	        }
75	        catch (NoSuchAlgorithmException e) {
76	            throw new IllegalStateException("SHA-256 not available", e);
77	        }
78	    }
