3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import tools.jackson.databind.ObjectMapper;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	
12	/**
13	 * Emits an immutable, structured {@code OWNER_CREATED} event on the dedicated {@code AUDIT} logger,
14	 * in addition to the human-readable line from {@link AuditOwnerCreated}. Runs after {@link SaveOwner}
15	 * (so the owner has its persisted id) and after {@link AssignCustomerCode} / {@link AssignMembershipLevel}.
16	 *
17	 * <p>The event is a JSON object {@code {seq, ownerId, customerCode, membershipLevel, event}} where
18	 * {@code seq} is a monotonically increasing integer across creates. It carries the owner's <em>current
19	 * primary identifier</em>: today that is the {@code customerCode} (see {@link #primaryIdentifier}).
20	 * When the customerCode is later unified into the memberId, only {@link #primaryIdentifier} and the
21	 * {@link OwnerCreatedEvent} field change, so the event then carries the memberId instead.
22	 */
23	public class AuditOwnerCreatedEvent {
24	
25	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
26	
27	    /** Monotonic across all creates in this process; not reset by per-request transactions. */
28	    private static final AtomicLong SEQ = new AtomicLong();
29	
30	    /** Immutable structured create event. Field order is the serialized JSON order. */
31	    public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
32	            Integer membershipLevel, String event) {
33	    }
34	
35	    public void service(@Val Owner owner, ObjectMapper mapper) {
36	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
37	                primaryIdentifier(owner), owner.getMembershipLevel(), "OWNER_CREATED");
38	        AUDIT.info(mapper.writeValueAsString(event));
39	    }
40	
41	    /**
42	     * The owner's current primary identifier. Currently the {@code customerCode}; this is the single
43	     * point that later moves to {@code owner.getMemberId()} when the two are unified.
44	     */
45	    private static String primaryIdentifier(Owner owner) {
46	        return owner.getCustomerCode();
47	    }
48	}
